pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // 1. Restrict to admissible domain: caller must be the current owner for transferOwnership to succeed.
        //    The fuzzer provides arbitrary caller/newOwner; we filter to only calls that can succeed.
        vm.assume(caller == c.owner());

        // 2. Attempt the transfer as the owner.
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // 3. Assert: after a successful transfer, the new owner must equal the passed _newOwner.
        assertEq(c.owner(), newOwner);
    }
}

