pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address currentOwner, address newOwner, address maliciousCaller) public {
        vm.assume(currentOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(maliciousCaller != address(0));
        vm.assume(currentOwner != maliciousCaller);
        vm.assume(newOwner != currentOwner);

        vm.prank(currentOwner);
        c.transferOwnership(currentOwner);

        address ownerBefore = c.owner();
        bool reverted = false;
        vm.prank(maliciousCaller);
        try c.transferOwnership(newOwner) {
        } catch {
            reverted = true;
        }
        address ownerAfter = c.owner();

        assertTrue(reverted && ownerAfter == ownerBefore);
    }
}

