pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, bool callerIsOwner) public {
        address caller = callerIsOwner ? c.owner() : address(uint160(uint256(keccak256(abi.encodePacked(c.owner(), newOwner)))));
        vm.assume(caller != c.owner() || newOwner != c.owner());
        vm.assume(caller != address(0));
        vm.prank(caller);
        try c.transferOwnership(newOwner) {} catch { return; }
        if (caller == c.owner()) {
            assertEq(c.owner(), newOwner);
        } else {
            assertEq(c.owner(), caller);
        }
    }
}

