pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _ownerTo, address _newOwner) public {
        vm.assume(_ownerTo != _newOwner);
        vm.assume(_ownerTo != address(0));
        vm.assume(_newOwner != address(0));

        // Set initial owner
        vm.prank(_ownerTo);
        c.transferOwnership(_ownerTo);

        // Transfer ownership
        vm.prank(_ownerTo);
        c.transferOwnership(_newOwner);

        // Assert: new owner must be the one we transferred to
        assertTrue(c.owner() == _newOwner);
    }
}

